    reduce<G>(fn: (acc: G, v: T, k: H) => G, initial: G): G;
    forEachKV(fn: (v: T, k: H, map: this) => void): void;
    invert(): M2<T, H>;
    group<G>(fn: (v: T, k: H) => G): M2<G, AR<T>>;
